import itertools
from typing import Optional


class Helpdesk:
    PRIORITIES = ("normal", "high", "critical")

    def __init__(self) -> None:
        self._customers: dict[str, bool] = {}
        self._id_counter = itertools.count(1)
        # ticket_id -> dict with customer, title, priority, state
        self._tickets: dict[int, dict] = {}
        # queue stored as a heap of (priority_key, ticket_id)
        import heapq
        self._heap: list[tuple] = []
        heapq.heapify(self._heap)
        self._heapq = heapq

    def add_customer(self, name: str, vip: bool = False) -> None:
        self._customers[name] = vip

    def open_ticket(self, customer: str, title: str, priority: str = "normal") -> int:
        if not title:
            raise ValueError("Ticket title must not be empty")
        if priority not in self.PRIORITIES:
            raise ValueError(f"Invalid priority: {priority}")
        if customer not in self._customers:
            # Allow implicit customer registration as non-VIP
            self._customers[customer] = False
        ticket_id = next(self._id_counter)
        self._tickets[ticket_id] = {
            "customer": customer,
            "title": title,
            "priority": priority,
            "state": "open",
        }
        self._enqueue(ticket_id)
        return ticket_id

    def _priority_key(self, ticket_id: int) -> tuple:
        ticket = self._tickets[ticket_id]
        is_vip = self._customers.get(ticket["customer"], False)
        priority_rank = self.PRIORITIES.index(ticket["priority"])
        # Lower tuple sorts first: VIP first, then priority (critical highest -> negate),
        # then ticket id ascending (FIFO within same priority).
        return (0 if is_vip else 1, -priority_rank, ticket_id)

    def _enqueue(self, ticket_id: int) -> None:
        self._heapq.heappush(self._heap, self._priority_key(ticket_id))

    def next_ticket(self) -> Optional[int]:
        while self._heap:
            key = self._heapq.heappop(self._heap)
            ticket_id = key[-1]
            ticket = self._tickets.get(ticket_id)
            if ticket is None or ticket["state"] != "open":
                continue
            ticket["state"] = "in_progress"
            return ticket_id
        return None

    def close(self, ticket_id: int) -> None:
        if ticket_id not in self._tickets:
            raise ValueError(f"Unknown ticket id: {ticket_id}")
        ticket = self._tickets[ticket_id]
        if ticket["state"] == "closed":
            raise ValueError(f"Ticket {ticket_id} is already closed")
        ticket["state"] = "closed"

    def reopen(self, ticket_id: int) -> None:
        if ticket_id not in self._tickets:
            raise ValueError(f"Unknown ticket id: {ticket_id}")
        ticket = self._tickets[ticket_id]
        if ticket["state"] == "closed":
            raise ValueError(f"Cannot reopen closed ticket {ticket_id}")
        if ticket["state"] == "open":
            raise ValueError(f"Ticket {ticket_id} is already open")
        ticket["state"] = "open"
        self._enqueue(ticket_id)
